// ***************
// Filename: blur_filter_top.sv
// Author: FPGA Cores 4 U
// Description: blur_filter with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map blur_filter_regs
//   (u_regs, src/include/blur_filter_regs.sv, ID "BLRF", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic conv2d_filter (u_core,
//   src/conv2d_filter.sv), joined by their register ports (cfg_* to the
//   logic, sts_* back). Generated by ip/scripts/regmap_gen.py from
//   blur_filter_regs.json and the ports of conv2d_filter: regenerate after
//   changing either. Clock - clk. Reset - synchronous active low rst_n.
// Date: 2026-10-11
module blur_filter_top #(
  parameter int N = 5,
  parameter int C = 3,
  parameter int CW = 8,
  parameter int COEF_W = 12,
  parameter int MAX_W = 2048,
  parameter int BORDER = 0,
  parameter logic [15:0] RESET_W = 16'd1920,
  parameter logic [15:0] RESET_H = 16'd1080
) (
  input  logic            clk,
  input  logic            rst_n,
  input  logic [7:0]      s_axil_awaddr,
  input  logic            s_axil_awvalid,
  output logic            s_axil_awready,
  input  logic [31:0]     s_axil_wdata,
  input  logic [3:0]      s_axil_wstrb,
  input  logic            s_axil_wvalid,
  output logic            s_axil_wready,
  output logic [1:0]      s_axil_bresp,
  output logic            s_axil_bvalid,
  input  logic            s_axil_bready,
  input  logic [7:0]      s_axil_araddr,
  input  logic            s_axil_arvalid,
  output logic            s_axil_arready,
  output logic [31:0]     s_axil_rdata,
  output logic [1:0]      s_axil_rresp,
  output logic            s_axil_rvalid,
  input  logic            s_axil_rready,
  input  logic [C*CW-1:0] s_axis_tdata,
  input  logic            s_axis_tlast,
  input  logic            s_axis_tuser,
  input  logic            s_axis_tvalid,
  output logic            s_axis_tready,
  output logic [C*CW-1:0] m_axis_tdata,
  output logic            m_axis_tlast,
  output logic            m_axis_tuser,
  output logic            m_axis_tvalid,
  input  logic            m_axis_tready
);
  // register ports between the register map and the logic
  logic [31:0] cfg_frame_size;
  logic [4:0] cfg_shift;
  logic [N*N*COEF_W-1:0] cfg_k;
  logic [31:0] sts_status;
  logic [31:0] sts_info;

  blur_filter_regs #(
    .N(N),
    .COEF_W(COEF_W),
    .RESET_W(RESET_W),
    .RESET_H(RESET_H),
    .KERNEL(conv2d_pkg::blur_kernel(N)),
    .SHIFT(conv2d_pkg::blur_shift(N))
  ) u_regs (
    .clk,
    .rst_n,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .frame_size_o(cfg_frame_size),
    .frame_size_wr_o(),
    .shift_o(cfg_shift),
    .shift_wr_o(),
    .status_i(sts_status),
    .info_i(sts_info),
    .k_o(cfg_k),
    .k_wr_o()
  );
  conv2d_filter #(
    .N(N),
    .C(C),
    .CW(CW),
    .COEF_W(COEF_W),
    .MAX_W(MAX_W),
    .BORDER(BORDER)
  ) u_core (
    .clk,
    .rst_n,
    .cfg_frame_size,
    .cfg_shift,
    .cfg_k,
    .sts_status,
    .sts_info,
    .s_axis_tdata,
    .s_axis_tlast,
    .s_axis_tuser,
    .s_axis_tvalid,
    .s_axis_tready,
    .m_axis_tdata,
    .m_axis_tlast,
    .m_axis_tuser,
    .m_axis_tvalid,
    .m_axis_tready
  );
endmodule
